class Job(RaskModel):
    """
    Asynchronous work started through v3, and automatic follow-up work (auto-dub, on-screen auto-start, the stages of
    a localization run) on projects created through v3. Started by 202 responses (`Location: /v3/jobs/{id}`); wait
    with getJob `wait_seconds`. Finished jobs can be read for 90 days, then answer 404 `job_not_found`. Work started
    in the web app or API v2 has no job.
    """
