    """Job type. Open enum: new types are added over time."""
    status: JobStatus
    """Job status. Monotonic: never goes backwards and never leaves a terminal state."""
    progress: Optional[int]
    """0-100; null when the type has no honest progress."""
    stage: Optional[JobStage]
    """Per-type stage; for a `localization` job, the running stage's."""
    queue_position: Optional[int]
    """Queue position (1 = next)."""
    estimated_finish_at: Optional[_dt.datetime]
    """
    Estimated completion from the queue position and the type's typical duration (on-screen: the runner's ETA); null
    when terminal or unknown. An estimate, not a deadline.
    """
    overdue: bool
    """
    True once the job runs past its type's overdue threshold: Rask is alerted. Keep waiting or check back later; do
    not start the same work again.
    """
    project_id: Optional[str]
    """Project."""
    media_id: Optional[str]
    """Media."""
    parent_job_id: Optional[str]
    """
    The job that started this system job: the project_processing job of an auto-dub, the dub whose merge started an
    on-screen auto-start, the `localization` job of a stage, the project_processing job o...
    """
    channel: JobChannel
    """
    Who started a job. - `api`: REST API v3 - `mcp`: the Rask MCP server - `system`: automatic (auto-dub, on-screen
    auto-start, the stages of a localization run)
    """
    params: JobParams
    """Normalized request echo: a union on `type` (= Job.type)."""
    details: Optional[JobDetails]
    """Live per-type state."""
    stages: Optional[List[LocalizationStage]]
    """The stages of a `localization` job in run order; null for other types."""
    cost: Optional[Cost]
    """
    Quoted at creation; `charged` turns true once the charge is committed. A `localization` job has no charge of its
    own: `minutes` is the sum of its stages charged and not refunded so far, `charged` i...
    """
    result: Optional[JobResult]
    """Set when succeeded; a failed `segment_generation` job may also list clips already voiced."""
    error: Optional[Problem]
    """
    Set when failed; on a canceled job only for the cancellation reason `project_deleted` (the project was deleted
    while the job ran; its work is discarded, refunded only for on-screen); `instance` is...
    """
    created_at: _dt.datetime
    """Creation time."""
    started_at: Optional[_dt.datetime]
    """Start time."""
    finished_at: Optional[_dt.datetime]
    """End time."""
    links: JobLinks
    """Path-absolute API links."""


