class SpendLimit(RaskModel):
    """
    The calling key's monthly spend caps. Pending deferred spends (a stored auto-dub or on-screen auto-start, the
    remaining stages of a localization run) count against the cap; a pool's limit and remaining values are null when
    that pool is uncapped.
    """
    limit_minutes: Optional[int]
    """The key's monthly cap on the minutes pool; null when uncapped."""
    spent_minutes: int
    """
    Minutes quoted by this key's jobs this UTC month, refunds excluded, plus its pending deferred spends. A
    `localization` job is not counted; its stages are.
    """
    remaining_minutes: Optional[int]
    """Minutes left under the cap; null when uncapped."""
    limit_projects: Optional[int]
    """The key's monthly cap on project credits; null when uncapped."""
    spent_projects: int
    """Project credits quoted by this key's jobs this UTC month, refunds excluded."""
    remaining_projects: Optional[int]
    """Project credits left under the cap; null when uncapped."""
    resets_at: _dt.datetime
    """Start of the next UTC month."""


